// A simple class to demonstrate lifecycle.
class Resource {
public:
    Resource() { std::cout << "Resource acquired\n"; }
    ~Resource() { std::cout << "Resource destroyed\n"; }
    void use() { std::cout << "Using resource...\n"; }
};

// Factory function returning a unique pointer, transferring ownership to the caller.
std::unique_ptr<Resource> createResource() {
    return std::make_unique<Resource>();
}

void takeOwnership(std::unique_ptr<Resource> res) {
    std::cout << "Ownership taken by function.\n";
    res->use();
} // `res` goes out of scope here, destroying the Resource.

int main() {
    // p1 now has exclusive ownership of the new Resource.
    std::unique_ptr<Resource> p1 = createResource();

    // std::unique_ptr<Resource> p2 = p1; // COMPILE ERROR: Cannot copy a unique_ptr.

    // Ownership is explicitly transferred from p1 to p2.
    // p1 becomes nullptr after this line.
    std::unique_ptr<Resource> p2 = std::move(p1);

    if (p2) {
        p2->use();
    }

    // Ownership is transferred to the function.
    // p2 becomes nullptr.
    takeOwnership(std::move(p2));

    std::cout << "Main function ending.\n";
}
